import{_ as i,C as l,o as t,c as s,a2 as o,b as n,w as a,a as c,E as d,a3 as p}from"./chunks/framework.RycU2wFZ.js";const b=JSON.parse('{"title":"Model Context Protocol (MCP) Server","description":"","frontmatter":{},"headers":[],"relativePath":"mcp/overview.md","filePath":"mcp/overview.md","lastUpdated":null}'),g={name:"mcp/overview.md"};function u(m,e,h,f,y,x){const r=l("Mermaid");return t(),s("div",null,[e[1]||(e[1]=o('<h1 id="model-context-protocol-mcp-server" tabindex="-1">Model Context Protocol (MCP) Server <a class="header-anchor" href="#model-context-protocol-mcp-server" aria-label="Permalink to &quot;Model Context Protocol (MCP) Server&quot;">​</a></h1><p>The <strong>Geomilli MCP Server</strong> (<code>geomilli-mcp</code>) is a lightweight, stateless adapter that exposes Geomilli&#39;s high-performance geospatial search engine, OpenStreetMap (OSM) index, and administrative taxonomy directly to AI agents, LLMs, and developer tools using the <a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol (MCP)</a>.</p><p>Built with the official <a href="https://github.com/modelcontextprotocol/go-sdk" target="_blank" rel="noreferrer"><code>github.com/modelcontextprotocol/go-sdk</code></a> (v1.x) in Go 1.25, it bridges natural language reasoning with sub-10ms spatial search, forward/reverse geocoding, proximity discovery, and aviation intelligence.</p><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>Geomilli MCP follows a strict <strong>adapter-only architecture</strong>. It never accesses Meilisearch or SQLite databases directly. Instead, it translates structured MCP tool, resource, and prompt requests into validated calls against the upstream <code>geomilli-api</code> REST service (<code>/v1/*</code>).</p>',6)),(t(),n(p,null,{default:a(()=>[d(r,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Clients%5B%22MCP%20Clients%20%26%20Agents%22%5D%0A%20%20%20%20%20%20%20%20CD%5B%22Claude%20Desktop%20%2F%20Claude%20Code%22%5D%0A%20%20%20%20%20%20%20%20CR%5B%22Cursor%20%2F%20VS%20Code%22%5D%0A%20%20%20%20%20%20%20%20AG%5B%22Antigravity%20%2F%20Custom%20Agents%22%5D%0A%20%20%20%20%20%20%20%20RA%5B%22Remote%20AI%20Systems%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20MCP%5B%22geomilli-mcp%20(%3A8090%20%2F%20stdio)%22%5D%0A%20%20%20%20%20%20%20%20T%5B%22Tool%20%2F%20Resource%20%2F%20Prompt%20Registry%22%5D%0A%20%20%20%20%20%20%20%20V%5B%22Input%20Validation%20%26%20Clamp%20Logic%22%5D%0A%20%20%20%20%20%20%20%20TC%5B%22Taxonomy%20%26%20Language%20TTL%20Cache%22%5D%0A%20%20%20%20%20%20%20%20F%5B%22Response%20Shaper%20(Token-Efficient)%22%5D%0A%20%20%20%20%20%20%20%20RC%5B%22Typed%20REST%20API%20Client%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Core%5B%22Geomilli%20Backend%22%5D%0A%20%20%20%20%20%20%20%20API%5B%22geomilli-api%20(%3A8080)%22%5D%0A%20%20%20%20%20%20%20%20MS%5B(%22Meilisearch%22)%5D%0A%20%20%20%20%20%20%20%20HV%5B%22geomilli-harvester%20(%3A8085)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20CD%20--%20%22stdio%22%20--%3E%20T%0A%20%20%20%20CR%20--%20%22stdio%20%2F%20http%22%20--%3E%20T%0A%20%20%20%20AG%20--%20%22stdio%20%2F%20http%22%20--%3E%20T%0A%20%20%20%20RA%20--%20%22Streamable%20HTTP%20(%3A8090%2Fmcp)%22%20--%3E%20T%0A%0A%20%20%20%20T%20--%3E%20V%20--%3E%20TC%20--%3E%20RC%0A%20%20%20%20RC%20--%20%22HTTP%20%2Fv1%2F*%22%20--%3E%20API%0A%20%20%20%20API%20--%3E%20MS%0A%20%20%20%20API%20--%20%22importer%20proxy%22%20--%3E%20HV%0A%20%20%20%20RC%20--%3E%20F%20--%3E%20T%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="architectural-highlights" tabindex="-1">Architectural Highlights <a class="header-anchor" href="#architectural-highlights" aria-label="Permalink to &quot;Architectural Highlights&quot;">​</a></h3><ul><li><strong>Stateless &amp; Horizontally Scalable</strong>: <code>geomilli-mcp</code> holds no persistent in-memory state. You can run multiple instances behind a load balancer with zero coordination.</li><li><strong>Single Source of Truth</strong>: All geospatial business logic, typo tolerance, coordinate clamping, and ranking algorithms remain centralized in <code>geomilli-api</code>.</li><li><strong>Config-Driven Enums</strong>: Category classes (<code>class</code>) and language codes (<code>lang</code>) are dynamically pulled from <code>/v1/taxonomy</code> and <code>/v1/languages</code> at startup and refreshed periodically. No taxonomy logic is ever hardcoded.</li><li><strong>Token Efficiency</strong>: Raw OSM records contain extensive tag maps and alternative names. <code>geomilli-mcp</code> shapes results into compact DTOs (<code>CompactPlace</code>) and human-readable text summaries, saving up to 70% of LLM context window tokens.</li><li><strong>Protocol Safety</strong>: In <code>stdio</code> mode, all operational and diagnostic logging is strictly routed to <code>stderr</code> using structured <code>log/slog</code>. Standard output (<code>stdout</code>) is reserved exclusively for JSON-RPC MCP messages to prevent transport corruption.</li></ul><hr><h2 id="dual-transport-support" tabindex="-1">Dual Transport Support <a class="header-anchor" href="#dual-transport-support" aria-label="Permalink to &quot;Dual Transport Support&quot;">​</a></h2><p>Geomilli MCP supports both official transports defined by the Model Context Protocol specification:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;"><code>stdio</code> Transport (Default)</th><th style="text-align:left;">Streamable <code>http</code> Transport</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Execution Mode</strong></td><td style="text-align:left;">Local subprocess launched by the MCP client.</td><td style="text-align:left;">Independent HTTP service listening on <code>:8090</code>.</td></tr><tr><td style="text-align:left;"><strong>Typical Use Cases</strong></td><td style="text-align:left;">Claude Desktop, Claude Code, Cursor, local IDE agents.</td><td style="text-align:left;">Docker Compose clusters, remote agents, cloud deployments.</td></tr><tr><td style="text-align:left;"><strong>Network Attack Surface</strong></td><td style="text-align:left;">Zero (isolated to the host process tree).</td><td style="text-align:left;">Protected by Bearer token auth &amp; Origin allowlists.</td></tr><tr><td style="text-align:left;"><strong>Endpoint</strong></td><td style="text-align:left;">Standard Input / Output (<code>stdin</code>/<code>stdout</code>).</td><td style="text-align:left;"><code>POST /mcp</code> (Stateless Streamable HTTP).</td></tr><tr><td style="text-align:left;"><strong>Logging</strong></td><td style="text-align:left;">Structured JSON strictly on <code>stderr</code>.</td><td style="text-align:left;">Structured JSON on standard logging outputs.</td></tr><tr><td style="text-align:left;"><strong>Health Probe</strong></td><td style="text-align:left;">Process exit code / MCP <code>ping</code>.</td><td style="text-align:left;">Native HTTP health check on <code>GET /healthz</code>.</td></tr></tbody></table><hr><h2 id="capabilities-overview" tabindex="-1">Capabilities Overview <a class="header-anchor" href="#capabilities-overview" aria-label="Permalink to &quot;Capabilities Overview&quot;">​</a></h2><p>Geomilli MCP exposes 16 tools, 5 resources, and 3 workflow prompts:</p><h3 id="_1-geospatial-tools-16-total" tabindex="-1">1. Geospatial Tools (16 Total) <a class="header-anchor" href="#_1-geospatial-tools-16-total" aria-label="Permalink to &quot;1. Geospatial Tools (16 Total)&quot;">​</a></h3><p>Tools are organized into functional tiers and categories:</p><ul><li><strong>Geocoding &amp; Location Lookups</strong>: <ul><li><a href="/docs/mcp/tools-reference#1-geocode"><code>geocode</code></a>: Resolve names, addresses, or queries into coordinate points and enclosing administrative hierarchies.</li><li><a href="/docs/mcp/tools-reference#2-reverse-geocode"><code>reverse_geocode</code></a>: Determine the address, administrative hierarchy, and closest landmark for any coordinate pair.</li></ul></li><li><strong>Spatial Discovery &amp; POI Search</strong>: <ul><li><a href="/docs/mcp/tools-reference#3-search-places"><code>search_places</code></a>: Full-text search with structured taxonomy, country, cuisine, and star rating filters.</li><li><a href="/docs/mcp/tools-reference#4-find-nearby"><code>find_nearby</code></a>: Radial proximity search around coordinates with distance sorting.</li><li><a href="/docs/mcp/tools-reference#5-places-in-area"><code>places_in_area</code></a>: Viewport bounding-box queries (<code>min_lat</code>, <code>min_lng</code>, <code>max_lat</code>, <code>max_lng</code>).</li><li><a href="/docs/mcp/tools-reference#6-get-place"><code>get_place</code></a>: Deep inspection by OSM primary identifier or Wikidata QID.</li></ul></li><li><strong>Aviation &amp; Transit Intelligence</strong>: <ul><li><a href="/docs/mcp/tools-reference#7-find-airports"><code>find_airports</code></a>: Search international, domestic, and regional airports by name, IATA, ICAO, or coordinate proximity.</li><li><a href="/docs/mcp/tools-reference#8-get-airport"><code>get_airport</code></a>: Retrieve full airport specifications by 3-letter IATA or 4-letter ICAO code.</li></ul></li><li><strong>Administrative Hierarchy</strong>: <ul><li><a href="/docs/mcp/tools-reference#9-list-countries"><code>list_countries</code></a>: Discover which countries are indexed in the Geomilli database.</li><li><a href="/docs/mcp/tools-reference#10-list-regions"><code>list_regions</code></a>: Query states, provinces, and regions for a given country code.</li><li><a href="/docs/mcp/tools-reference#11-list-cities"><code>list_cities</code></a>: List major cities and settlements ordered by population and popularity.</li></ul></li><li><strong>Reference &amp; Utilities</strong>: <ul><li><a href="/docs/mcp/tools-reference#12-list-place-categories"><code>list_place_categories</code></a>: Inspect the 19 canonical taxonomy categories and scoring weights.</li><li><a href="/docs/mcp/tools-reference#13-measure-distance"><code>measure_distance</code></a>: Exact Haversine great-circle distance calculation between two points or place IDs.</li></ul></li><li><strong>Operations &amp; Cluster Telemetry (Gated)</strong>: <ul><li><a href="/docs/mcp/tools-reference#14-get-service-status"><code>get_service_status</code></a>: Inspect API health, harvester daemon state, and search metrics.</li><li><a href="/docs/mcp/tools-reference#15-list-import-queue"><code>list_import_queue</code></a>: Inspect the active country ingestion pipeline and worker queues.</li><li><a href="/docs/mcp/tools-reference#16-list-importable-countries"><code>list_importable_countries</code></a>: View all countries supported for ingestion.</li></ul></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Tier-2 operations tools are disabled by default. They can be enabled by setting <code>MCP_ENABLE_OPS_TOOLS=true</code>.</p></div><h3 id="_2-context-resources-geomilli" tabindex="-1">2. Context Resources (<code>geomilli://</code>) <a class="header-anchor" href="#_2-context-resources-geomilli" aria-label="Permalink to &quot;2. Context Resources (`geomilli://`)&quot;">​</a></h3><p>Resources provide read-only context documents that LLMs can load directly into their reasoning context:</p><ul><li><code>geomilli://taxonomy</code>: Canonical place categories, match rules, and base scores.</li><li><code>geomilli://languages</code>: Supported language whitelist and localized display names.</li><li><code>geomilli://countries</code>: Indexed countries with entity counts.</li><li><code>geomilli://schema/place</code>: Markdown documentation of the <code>Place</code> document schema and coordinate formats.</li><li><code>geomilli://places/{id}</code>: Dynamic URI template for retrieving full place documents by ID.</li></ul><p>For complete documentation, see the <a href="/docs/mcp/resources-and-prompts">Resources &amp; Prompts Guide</a>.</p><h3 id="_3-guided-workflow-prompts" tabindex="-1">3. Guided Workflow Prompts <a class="header-anchor" href="#_3-guided-workflow-prompts" aria-label="Permalink to &quot;3. Guided Workflow Prompts&quot;">​</a></h3><p>Predefined prompt templates guide LLMs through complex multi-step spatial reasoning workflows:</p><ul><li><code>explore_area</code>: Forward geocodes a destination and discovers curated attractions, dining, and cultural sights.</li><li><code>describe_location</code>: Reverse geocodes coordinates and synthesizes a vivid administrative and geographical narrative.</li><li><code>plan_airport_transfer</code>: Discovers airports serving a city, measures direct transit distances, and compares transit options.</li></ul><hr><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><ol><li><strong>Configure your AI client</strong>: Read the <a href="/docs/mcp/client-setup">Client Setup Guide</a> for copy-paste configurations for Claude Desktop, Claude Code, Cursor, and VS Code.</li><li><strong>Explore available tools</strong>: Review parameter definitions and sample outputs in the <a href="/docs/mcp/tools-reference">Tools Reference</a>.</li><li><strong>Deploy to production</strong>: Consult the <a href="/docs/mcp/security-and-deployment">Security &amp; Deployment Guide</a> for Docker Compose, Kubernetes, Bearer authentication, and Origin filtering.</li></ol>',23))])}const C=i(g,[["render",u]]);export{b as __pageData,C as default};
